USING (SELECT '100001' AS EMPNO FROM dual) s ON (t.EMPNO = s.EMPNO)
WHEN MATCHED THEN UPDATE SET NAME='Avanish Gupta', POSTING_SOL_ID='7115', POSTING_SOL_DESC='DIT-SWDC HEAD OFFICE', SCALE_CODE='3', CADRE_CODE='OFFR',
  POSTING_REGION_NAME='HEAD OFFICE', DESIG='Software Developer', MOBILE_NO='9876543210', E_MAIL='avanish.gupta@uco.bank.in'
WHEN NOT MATCHED THEN INSERT (EMPNO, NAME, POSTING_SOL_ID, POSTING_SOL_DESC, SCALE_CODE, CADRE_CODE, POSTING_REGION_NAME, DESIG, MOBILE_NO, E_MAIL)
  VALUES ('100001','Avanish Gupta','7115','DIT-SWDC HEAD OFFICE','3','OFFR','HEAD OFFICE','Software Developer','9876543210','avanish.gupta@uco.bank.in');

